window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[259]={"id":"259","numero":259,"titre":"Protéinurie, syndrome néphrotique","objectifs":[{"id":"259-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la protéinurie physiologique","contenu":"<p>Chaque jour, <span class=\"kw-chiffre\">10 à 15 kg</span> de protéines sériques traversent le rein, mais seulement <span class=\"kw-chiffre\">100 à 150 mg</span> sont excrétés dans l'urine en <span class=\"kw-chiffre\">24 h</span>. Cette <span class=\"kw-def\"><strong>protéinurie physiologique</strong></span> résulte de <strong>deux barrières</strong> successives.</p>\n      <table >\n        <thead><tr><th>Barrière</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Filtration glomérulaire</strong></span><br>(paroi du capillaire)</td>\n            <td>\n              <ul>\n                <li><strong>Sélectivité de charge :</strong> les glycoprotéines de la <span class=\"kw-def\">MBG</span> chargées <span class=\"kw-clinique\">négativement</span> repoussent les protéines anioniques</li>\n                <li><strong>Sélectivité de taille :</strong> néphrine et podocine limitent le passage des grosses protéines ; passage négligeable si <span class=\"kw-alerte\">PM &gt; 68 000 Da</span> (= PM de l'<span class=\"kw-bio\">albumine</span>)</li>\n                <li>une molécule diffuse d'autant mieux qu'elle est <span class=\"kw-clinique\">petite</span> et <span class=\"kw-clinique\">chargée positivement</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Réabsorption tubulaire</strong></span><br>(tube proximal)</td>\n            <td>le tube contourné proximal <span class=\"kw-clinique\">réabsorbe la grande majorité</span> des protéines physiologiquement filtrées</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Composition de la <span class=\"kw-bio\">protéinurie</span> physiologique</strong></p>\n      <table >\n        <thead><tr><th>Fraction</th><th>Composition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Albumine</strong></span> (négligeable)</td><td>&lt;<span class=\"kw-chiffre\"> 30 mg</span>/j, soit &lt;<span class=\"kw-chiffre\"> 3 mg</span>/mmol, soit &lt;<span class=\"kw-chiffre\"> 30 mg</span>/g de créatininurie</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Protéines de faible PM</strong></span> (<span class=\"kw-chiffre\">60 %</span>)</td><td><span class=\"kw-bio\">lysozyme</span> · <span class=\"kw-bio\">β2-microglobuline</span> · chaînes légères <span class=\"kw-bio\">kappa</span> et <span class=\"kw-bio\">lambda</span> · <span class=\"kw-bio\">Retinol Binding Protein</span></td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Protéines sécrétées</strong></span> (<span class=\"kw-chiffre\">40 %</span>)</td><td>par l'urothélium des voies urinaires ; ou par le tubule — <span class=\"kw-bio\">uromoduline</span> (protéine de <span class=\"kw-bio\">Tamm-Horsfall</span>, branche ascendante de l'anse de Henlé)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Seuils physiologiques</strong> <span class=\"kw-def\">(1 g de créatinine = 10 mmol ; excrétion urinaire ≈ 1 g/j soit 10 mmol/j)</span></p>\n      <ul>\n        <li><span class=\"kw-def\">Protéinurie A1</span> (physiologique) : <span class=\"kw-chiffre\">&lt; 150 mg/j</span>, soit &lt;<span class=\"kw-chiffre\"> 150 mg</span>/g, soit &lt;<span class=\"kw-chiffre\"> 15 mg</span>/mmol de créatininurie</li>\n        <li><span class=\"kw-def\">Albuminurie A1</span> (physiologique) : <span class=\"kw-chiffre\">&lt; 30 mg/j</span>, soit &lt;<span class=\"kw-chiffre\"> 30 mg</span>/g, soit &lt;<span class=\"kw-chiffre\"> 3 mg</span>/mmol de créatininurie</li>\n      </ul>\n      <div class=\"obj-callout success\"><strong>À comprendre.</strong> La <span class=\"kw-bio\">protéinurie</span> physiologique est minime car la barrière glomérulaire filtre selon la <span class=\"kw-def\">charge</span> et la <span class=\"kw-def\">taille</span>, et le tube proximal réabsorbe quasiment tout ce qui passe. Une <span class=\"kw-bio\">protéinurie</span> pathologique traduit une <strong>rupture</strong> de l'un de ces deux mécanismes.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — Insuffisance rénale chronique · 261 — Néphropathie glomérulaire</em></p>","frequence":1},{"id":"259-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la protéinurie pathologique","contenu":"<p>Une <span class=\"kw-bio\">protéinurie</span> est <span class=\"kw-def\"><strong>pathologique</strong></span> lorsqu'elle est <span class=\"kw-clinique\">permanente</span> et dépasse les seuils physiologiques. La première étape est de distinguer une <span class=\"kw-bio\">protéinurie</span> <span class=\"kw-clinique\">permanente</span> (pathologique) d'une <span class=\"kw-bio\">protéinurie</span> <span class=\"kw-clinique\">intermittente / transitoire</span> (physiologique).</p>\n      <p><strong>Seuils de <span class=\"kw-bio\">protéinurie</span> et d'<span class=\"kw-bio\">albuminurie</span></strong></p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Protéinurie</th><th>Albuminurie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>A1</strong></span> (physiologique)</td><td>&lt;<span class=\"kw-chiffre\"> 150 mg</span>/j</td><td>&lt;<span class=\"kw-chiffre\"> 30 mg</span>/j (physiologique)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>A2</strong></span> (modérée)</td><td><span class=\"kw-chiffre\">150 – 500 mg</span>/j</td><td><span class=\"kw-chiffre\">30 – 300 mg</span>/j (<span class=\"kw-clinique\">microalbuminurie</span>)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>A3</strong></span> (importante)</td><td>&gt;<span class=\"kw-chiffre\"> 500 mg</span>/j</td><td>&gt;<span class=\"kw-chiffre\"> 300 mg</span>/j</td></tr>\n          <tr><td><span class=\"kw-alerte\"><strong>Syndrome néphrotique</strong></span></td><td><span class=\"kw-alerte\">≥ 3 g/24 h</span> (adulte) ; <span class=\"kw-chiffre\">≥ 50 mg/kg/j</span> ou <span class=\"kw-chiffre\">≥ 200 mg</span>/mmol (enfant)</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Protéinuries intermittentes ou transitoires (physiologiques)</strong> — elles <span class=\"kw-alerte\">n'entraînent JAMAIS</span> œdèmes, HTA, hypoalbuminémie ou insuffisance rénale. Découverte presque toujours <span class=\"kw-clinique\">fortuite</span>, n'excédant pas « ++ » à la BU ou <span class=\"kw-chiffre\">1 g</span>/<span class=\"kw-chiffre\">24 h</span>.</p>\n      <table >\n        <thead><tr><th>Type</th><th>Caractéristiques · CAT</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Effort · Fièvre</strong></span></td>\n            <td>apparaît au décours d'un <span class=\"kw-clinique\">exercice physique intense et prolongé</span> ou d'une <span class=\"kw-clinique\">fièvre prolongée</span> ; disparaît après régression de la fièvre ou <span class=\"kw-chiffre\">48 h</span> après l'effort → <span class=\"kw-ttt\">pas de bilan</span> si normalisation en <span class=\"kw-chiffre\">1 à 2 semaines</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Orthostatique</strong></span></td>\n            <td>période pubertaire (<span class=\"kw-chiffre\">12-16 ans</span>), adolescent longiligne ; présente sur une miction de <span class=\"kw-clinique\">fin de journée</span>, <span class=\"kw-clinique\">disparaît en clinostatisme</span> (urines du matin au réveil) ; <span class=\"kw-ttt\">aucun examen</span> une fois confirmée, disparaît spontanément avant <span class=\"kw-chiffre\">20 ans</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Circonstances « pathologiques »</strong></span></td>\n            <td>polyglobulie · infections de l'appareil urinaire · insuffisance ventriculaire droite</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Toute <span class=\"kw-bio\">protéinurie</span> <span class=\"kw-def\">permanente &gt; 0,5 g/j</span> justifie un <span class=\"kw-alerte\">avis néphrologique</span>. Une <span class=\"kw-bio\">protéinurie</span> transitoire de l'effort, de la fièvre ou orthostatique du sujet jeune ne nécessite <strong>aucun</strong> bilan une fois la disparition confirmée.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — Insuffisance rénale chronique · 224 — HTA</em></p>","frequence":1},{"id":"259-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les méthodes d’analyse d’une protéinurie","contenu":"<p>L'analyse d'une <span class=\"kw-bio\">protéinurie</span> combine une étape <span class=\"kw-clinique\">quantitative</span> (dépistage puis confirmation) et une étape <span class=\"kw-clinique\">qualitative</span> (composition par électrophorèse).</p>\n      <p><strong>1 · Bandelette urinaire</strong> — méthode semi-quantitative, la plus utilisée, de <span class=\"kw-clinique\">dépistage</span></p>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Principe</strong></span></td><td>détecte l'<span class=\"kw-bio\">albumine</span> lorsqu'elle est <span class=\"kw-chiffre\">&gt; 50-100 mg/L</span> ; <span class=\"kw-alerte\">ne détecte PAS</span> les chaînes légères d'Ig ni les protéines de bas poids moléculaire ❌</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Interprétation</strong></span></td><td><strong>Normal :</strong> – , traces (&lt;<span class=\"kw-chiffre\"> 0,3 g/L</span>) ou 1+ (≈<span class=\"kw-chiffre\"> 0,3 g/L</span>)<br><strong>Anormal :</strong> 2+ (≈<span class=\"kw-chiffre\"> 1 g/L</span>) · 3+ (≈<span class=\"kw-chiffre\"> 3 g/L</span>) · 4+ (&gt;<span class=\"kw-chiffre\"> 20 g/L</span>)</td></tr>\n          <tr><td><span class=\"kw-ci\"><strong>Faux positifs</strong></span></td><td>urines concentrées · chlorhexidine · <span class=\"kw-clinique\">hématurie macroscopique</span> · pH urinaire &gt; 8</td></tr>\n          <tr><td><span class=\"kw-ci\"><strong>Faux négatifs</strong></span></td><td>urines diluées · présence de protéines de faible PM (<span class=\"kw-etio\">chaînes légères du myélome</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>2 · Dosage pondéral</strong> — étape de <span class=\"kw-clinique\">confirmation</span></p>\n      <ul>\n        <li>soit sur la <span class=\"kw-clinique\">protéinurie des 24 h</span> : exprimée en <span class=\"kw-bio\">g/24 h</span></li>\n        <li>soit sur un <span class=\"kw-clinique\">échantillon</span> d'urine : par le <span class=\"kw-bio\">rapport protéinurie / créatininurie</span></li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Une <span class=\"kw-clinique\">hématurie macroscopique</span> ou une <span class=\"kw-clinique\">pyurie abondante</span> gênent l'interprétation : l'<span class=\"kw-bio\">hématurie</span> macroscopique génère elle-même une <span class=\"kw-bio\">protéinurie</span> <span class=\"kw-chiffre\">1-2 g/j</span> par <span class=\"kw-alerte\">hémolyse</span>.</div>\n      <p><strong>3 · Électrophorèse des protéines urinaires (EPU)</strong> — analyse <span class=\"kw-clinique\">qualitative</span> : elle identifie la <span class=\"kw-def\">protéine majoritaire</span> et oriente l'étiologie</p>\n      <table >\n        <thead><tr><th>Type</th><th>Protéine majoritaire</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Glomérulaire</strong></span></td>\n            <td><span class=\"kw-bio\">Albumine &gt; 60 %</span></td>\n            <td>néphropathies glomérulaires</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Tubulaire</strong></span></td>\n            <td>protéines de bas PM : <span class=\"kw-bio\">lysozymurie</span>, <span class=\"kw-bio\">β2-microglobulinurie</span></td>\n            <td>trouble de réabsorption tubulaire proximale : isolé (rare) ou <span class=\"kw-etio\">syndrome de Fanconi</span> (<span class=\"kw-def\">glycosurie, bicarbonaturie, phosphaturie, aminoacidurie</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Surcharge</strong></span></td>\n            <td>selon l'étiologie</td>\n            <td>dépassement des capacités de réabsorption : <span class=\"kw-etio\">myoglobine</span> (rhabdomyolyse) ; chaînes légères <span class=\"kw-bio\">kappa / lambda</span> (<span class=\"kw-etio\">myélome</span>, <span class=\"kw-etio\">amylose AL</span>) → <span class=\"kw-alerte\">immunofixation</span> indispensable pour caractériser la protéine monoclonale</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Discriminant clé.</strong> Une <span class=\"kw-bio\">protéinurie</span> <span class=\"kw-clinique\">abondante</span> n'est pas synonyme de <span class=\"kw-bio\">protéinurie</span> <span class=\"kw-def\">glomérulaire</span> : une <span class=\"kw-bio\">protéinurie</span> de <span class=\"kw-def\">surcharge</span> (myélome à chaînes légères) peut être très abondante. C'est la <span class=\"kw-alerte\">composition en albumine (EPU)</span> qui fait la différence — et il n'y a <strong>pas de syndrome néphrotique</strong> dans le myélome à chaînes légères.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 320 — Myélome multiple · 260 — Hématurie</em></p>","frequence":2},{"id":"259-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition du syndrome néphrotique","contenu":"<p>Le <span class=\"kw-def\"><strong>syndrome néphrotique (SN)</strong></span> a une définition <span class=\"kw-alerte\">strictement biologique</span> : il associe une <span class=\"kw-bio\">protéinurie</span> abondante et une hypoalbuminémie.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Adulte</th><th>Enfant</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Protéinurie</strong></span></td>\n            <td><span class=\"kw-alerte\">&gt; 3 g/24 h</span></td>\n            <td><span class=\"kw-alerte\">&gt; 50 mg/kg/24 h</span> ou <span class=\"kw-chiffre\">200 mg</span>/mmol ou <span class=\"kw-chiffre\">2 g</span>/g de créatininurie</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Hypoalbuminémie</strong></span></td>\n            <td colspan=\"2\"><span class=\"kw-alerte\">&lt; 30 g/L</span> <span class=\"kw-def\">(collège de pédiatrie : hypoalbuminémie et/ou hypoprotidémie &lt; 60 g/L)</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Syndrome néphrotique pur ou impur</strong></p>\n      <div class=\"callout callout-info\"><p style=\"margin:0 0 6px\"><strong>Le SN est PUR</strong> s'il n'est accompagné d'<strong>aucun</strong> des signes suivants ; la présence d'<span class=\"kw-alerte\">un seul</span> le rend <strong>IMPUR</strong> :</p>\n        <ul style=\"margin:0\">\n          <li><span class=\"kw-clinique\">Hématurie microscopique</span></li>\n          <li><span class=\"kw-clinique\">HTA</span></li>\n          <li><span class=\"kw-clinique\">Insuffisance rénale organique</span> <span class=\"kw-def\">(parfois difficile à distinguer initialement d'une IR fonctionnelle ⚠️)</span></li>\n        </ul>\n      </div>\n      <p><strong>Reconnaître un syndrome néphrotique</strong></p>\n      <table >\n        <thead><tr><th>Axe</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Révélation</strong></span></td>\n            <td><span class=\"kw-bio\">protéinurie</span> abondante d'un examen systématique (médecine du travail…) ; <span class=\"kw-alerte\">syndrome œdémateux</span> ⭐ (domine le tableau, installation explosive ou progressive) ; complication révélatrice</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Sang</strong></span></td>\n            <td><span class=\"kw-bio\">hypoalbuminémie &lt; 30 g/L</span> ; créatininémie variable ; EPP : <span class=\"kw-bio\">hypogammaglobulinémie</span>, élévation des <span class=\"kw-bio\">α2-globulines</span>, des β-globulines et du <span class=\"kw-bio\">fibrinogène</span> ; <span class=\"kw-clinique\">hyperlipidémie</span> fréquente (↑ cholestérol, ↑ <span class=\"kw-bio\">triglycérides</span>) ; hypoprotidémie + <span class=\"kw-bio\">hypocalcémie</span> (↓ fraction du Ca²⁺ lié à l'<span class=\"kw-bio\">albumine</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Urines</strong></span></td>\n            <td><span class=\"kw-bio\">protéinurie</span> permanente et abondante ; sédiment urinaire : recherche d'une <span class=\"kw-clinique\">hématurie microscopique</span> ; culot : recherche de <span class=\"kw-clinique\">cylindres hématiques</span> (origine glomérulaire)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> La définition du SN est <span class=\"kw-alerte\">100 % biologique</span> : <span class=\"kw-bio\">protéinurie &gt; 3 g/24 h</span> + <span class=\"kw-bio\">albuminémie &lt; 30 g/L</span>. Les œdèmes sont fréquents mais <strong>ne font pas partie</strong> de la définition. « Pur / impur » se juge sur 3 items : <span class=\"kw-clinique\">hématurie micro · HTA · IR organique</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 257 — Œdèmes des membres inférieurs · 264 — Insuffisance rénale chronique</em></p>","frequence":2},{"id":"259-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie du syndrome néphrotique","contenu":"<p>Le syndrome néphrotique résulte d'un <span class=\"kw-def\"><strong>trouble de la perméabilité du capillaire glomérulaire</strong></span>, responsable du passage d'une grande quantité d'<span class=\"kw-bio\">albumine</span> dans l'urine. Cinq mécanismes lésionnels peuvent l'expliquer.</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Substratum · exemple</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>Altération des podocytes</strong></span></td><td>atteinte du diaphragme de fente (effacement des pieds des podocytes)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Altération de l'endothélium</strong></span></td><td><span class=\"kw-etio\">microangiopathies thrombotiques</span></td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Anomalie de la MBG</strong></span></td><td>anomalie de structure de la membrane basale glomérulaire — <span class=\"kw-etio\">syndrome d'Alport</span></td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Perte des charges électronégatives</strong></span></td><td>perte des charges anioniques de la MBG — <span class=\"kw-etio\">SN à LGM</span> (facteur circulant suspecté, <span class=\"kw-alerte\">récidive après transplantation rénale</span>)</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Dépôts de protéines</strong></span></td><td>dépôts dans les glomérules — <span class=\"kw-etio\">glomérulonéphrite extra-membraneuse (GEM)</span>, <span class=\"kw-etio\">amyloses</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout success\"><strong>À comprendre.</strong> La sélectivité de la barrière glomérulaire repose normalement sur la <span class=\"kw-def\">charge</span> (MBG anionique) et la <span class=\"kw-def\">taille</span> (diaphragme de fente podocytaire). Toute lésion de l'un de ces éléments laisse fuir l'<span class=\"kw-bio\">albumine</span> → <span class=\"kw-bio\">protéinurie</span> glomérulaire massive et hypoalbuminémie.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 261 — Néphropathie glomérulaire · 260 — Hématurie</em></p>","frequence":0},{"id":"259-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’évaluation initiale d’un syndrome néphrotique chez l’adulte et chez l’enfant","contenu":"<p>L'évaluation initiale confirme le SN, en précise le caractère <span class=\"kw-clinique\">pur / impur</span> et débute l'orientation étiologique. Le bilan diffère légèrement entre l'adulte et l'enfant.</p>\n      <p><strong>Chez l'adulte</strong> (bilan d'une <span class=\"kw-bio\">protéinurie</span> permanente / d'un SN)</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Clinique</strong></span></td><td>œdèmes · pression artérielle · recherche d'une infection · signes généraux</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Sang</strong></span></td><td>créatininémie · <span class=\"kw-bio\">ionogramme</span> sanguin · <span class=\"kw-bio\">glycémie</span> · <span class=\"kw-bio\">électrophorèse des protéines sériques</span> (si &gt;<span class=\"kw-chiffre\"> 45 ans</span>) · albuminémie</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Urines</strong></span></td><td>sédiment urinaire / <span class=\"kw-bio\">ECBU</span> · <span class=\"kw-bio\">électrophorèse des protéines urinaires</span> (si &gt;<span class=\"kw-chiffre\"> 45 ans</span>)</td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Imagerie</strong></span></td><td><span class=\"kw-imagerie\">échographie</span> rénale</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Chez l'enfant</strong> (démarche orientée selon le contexte)</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Fièvre ou effort prolongé</span></td><td>contrôler à distance (<span class=\"kw-chiffre\">1 à 2 semaines</span>)</td></tr>\n          <tr><td>Absence de contexte et de signes</td><td>rechercher une <span class=\"kw-def\">protéinurie orthostatique</span> : 1ʳᵉ miction du matin au lever (vessie vidée au coucher) + miction de fin de journée</td></tr>\n          <tr><td>Signes cliniques ou <span class=\"kw-clinique\">protéinurie permanente</span></td><td><strong>Sang :</strong> <span class=\"kw-bio\">ionogramme</span>, créatininémie, <span class=\"kw-bio\">albuminémie / protidémie</span>, complément (<span class=\"kw-bio\">fraction C3</span>)<br><strong>Urines :</strong> <span class=\"kw-bio\">albuminurie</span>, <span class=\"kw-bio\">β2-microglobuline urinaire</span><br><strong>Imagerie :</strong> <span class=\"kw-imagerie\">échographie</span> rénale en 2ⁿᵈ intention (glomérulopathie éliminée ou avant biopsie)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Chez l'enfant, le dosage du <span class=\"kw-bio\">complément C3</span> et de la <span class=\"kw-bio\">β2-microglobuline urinaire</span> oriente d'emblée (GNA, atteinte tubulaire). Chez l'adulte de <span class=\"kw-chiffre\">&gt; 45 ans</span>, les électrophorèses sérique et urinaire deviennent systématiques (recherche d'une <span class=\"kw-etio\">gammapathie / amylose</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 264 — Insuffisance rénale chronique · 245 — Insuffisance surrénale (œdèmes/iono)</em></p>","frequence":1},{"id":"259-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications aiguës et chroniques du syndrome néphrotique","contenu":"<p>Les complications du SN se répartissent en complications <span class=\"kw-alerte\">aiguës</span> (à redouter à la phase initiale) et <span class=\"kw-clinique\">chroniques</span> (sur SN prolongé).</p>\n      <div class=\"callout callout-danger\">\n        <p style=\"margin:0 0 6px\"><strong>⚠️ Complications aiguës</strong></p>\n        <table >\n          <thead><tr><th>Complication</th><th>Mécanisme · particularités</th></tr></thead>\n          <tbody>\n            <tr>\n              <td><span class=\"kw-alerte\"><strong>Insuffisance rénale aiguë</strong></span></td>\n              <td><span class=\"kw-clinique\">IRA fonctionnelle</span> (hypovolémie relative) · <span class=\"kw-clinique\">NTA</span> (hypovolémie sévère et prolongée) · <span class=\"kw-alerte\">thrombose des veines rénales</span> (surtout GEM / amylose ; migration vers la VCI → <span class=\"kw-alerte\">risque d'EP</span> ⚠️)</td>\n            </tr>\n            <tr>\n              <td><span class=\"kw-alerte\"><strong>Thromboses</strong></span></td>\n              <td><strong>Territoires :</strong> tous, <span class=\"kw-clinique\">veineux</span> (sinus veineux cérébral, veines rénales +++) et surtout <span class=\"kw-clinique\">artériels</span><br><strong>Mécanisme :</strong> pertes urinaires de facteurs anticoagulants + synthèse accrue de facteurs procoagulants (V, VIII)<br><strong>Prévention :</strong> bas de contention · éviter la déplétion sodée brutale (&gt;<span class=\"kw-chiffre\"> 1-2 kg</span>/j) · <span class=\"kw-ttt\">anticoagulation</span> si hypoalbuminémie durable <span class=\"kw-chiffre\">&lt; 20 g/L</span></td>\n            </tr>\n            <tr>\n              <td><span class=\"kw-alerte\"><strong>Infections</strong></span></td>\n              <td><span class=\"kw-etio\">bactéries encapsulées</span> (pneumocoque, Haemophilus, Klebsielle, méningocoque) par hypogammaglobulinémie + fuite d'opsonines ; infection cutanée (érysipèle → cellulite) ; <span class=\"kw-etio\">péritonite primitive</span> à pneumocoque (enfant) ; grippe / varicelle maligne<br><strong>Prévention :</strong> vaccinations <span class=\"kw-ttt\">anti-grippale</span> et <span class=\"kw-ttt\">anti-pneumococcique</span> — <span class=\"kw-alerte\">PAS d'antibioprophylaxie</span> ❌</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n      <p><strong>Complications chroniques</strong></p>\n      <table >\n        <thead><tr><th>Complication</th><th>Mécanisme · prise en charge</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>HTA</strong></span></td><td>très fréquente sur glomérulonéphrite chronique → néphroprotection (&lt;<span class=\"kw-chiffre\"> 6 g</span>/j de sel, <span class=\"kw-ttt\">IEC/ARA2</span> puis diurétique)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>IRC</strong></span></td><td>glomérulopathie + effet néphrotoxique de la <span class=\"kw-bio\">protéinurie</span> sur le tubule (fibrose interstitielle) + HTA non contrôlée</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Hyperlipidémie</strong></span></td><td>↑ production hépatique de lipoprotéines (VLDL, <span class=\"kw-bio\">LDL</span>) + ↓ catabolisme ; profil <span class=\"kw-clinique\">mixte</span>, hypercholestérolémie parfois majeure (&gt;<span class=\"kw-chiffre\"> 10 mmol/L</span>), athérogène ; <span class=\"kw-clinique\">corrélée à la sévérité</span> du SN ; <span class=\"kw-ttt\">statine</span> si SN durable (&gt;<span class=\"kw-chiffre\"> 6 mois</span>) résistant (HSF, GEM)</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Dénutrition protidique</strong></span></td><td>atrophie musculaire (après <span class=\"kw-ttt\">corticothérapie</span> prolongée) ; <span class=\"kw-clinique\">retard de croissance</span> de l'enfant (CTC bloquent le pic pubertaire) ; régime normoprotidique <span class=\"kw-chiffre\">1-1,5 g/kg/j</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Médicaments</strong></span></td><td>↑ fraction libre plasmatique des médicaments liés à l'<span class=\"kw-bio\">albumine</span> → <span class=\"kw-alerte\">risque de surdosage</span> : <span class=\"kw-ttt\">AVK, AINS, statines</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Métabolique</strong></span></td><td>↓ métaux (fer, cuivre, zinc) ; ↓ protéines porteuses (vitamine-D-binding protein, TBG, céruléoplasmine, <span class=\"kw-bio\">transferrine</span>) → <span class=\"kw-bio\">carence en vitamine D</span>, <span class=\"kw-bio\">hypothyroïdie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Les 3 complications aiguës « réflexes » du SN : <span class=\"kw-alerte\">thrombose</span> (dont veine rénale → EP), <span class=\"kw-alerte\">infection</span> à germes encapsulés, <span class=\"kw-alerte\">IRA</span>. L'<span class=\"kw-ttt\">anticoagulation</span> préventive se discute dès que l'albuminémie est <span class=\"kw-chiffre\">&lt; 20 g/L</span> de façon durable.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — Maladie thrombo-embolique veineuse · 224 — HTA · 223 — Dyslipidémies · 146 — Vaccinations</em></p>","frequence":0},{"id":"259-8","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes des œdèmes du syndrome néphrotique","contenu":"<p>Les œdèmes du SN résultent d'une <span class=\"kw-def\">rétention hydrosodée</span> dont le moteur principal est l'<span class=\"kw-bio\">hypoalbuminémie</span>.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>1 · Hypoalbuminémie</strong></span></td><td>la fuite urinaire massive d'<span class=\"kw-bio\">albumine</span> abaisse la <span class=\"kw-clinique\">pression oncotique</span> plasmatique</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>2 · Transfert vers l'interstitium</strong></span></td><td>la chute de pression oncotique favorise le passage d'eau et de sodium du secteur <span class=\"kw-clinique\">vasculaire</span> vers le secteur <span class=\"kw-clinique\">interstitiel</span> → œdèmes</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>3 · Rétention hydrosodée rénale</strong></span></td><td>l'hypovolémie efficace active les systèmes de rétention (SRAA) ; une <span class=\"kw-clinique\">rétention sodée rénale primitive</span> participe également → entretien et aggravation des œdèmes</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Diagnostics différentiels</strong> — distinguer le SN des autres causes d'œdèmes généralisés <span class=\"kw-clinique\">sans protéinurie</span> :\n        <ul style=\"margin:6px 0 0\">\n          <li><strong>Avec rétention sodée :</strong> <span class=\"kw-etio\">cirrhose</span>, <span class=\"kw-etio\">insuffisance cardiaque</span>, <span class=\"kw-etio\">péricardite constrictive</span> <span class=\"kw-def\">(IC droite sévère et cirrhose peuvent parfois s'accompagner d'une protéinurie)</span></li>\n          <li><strong>Autres hypoprotidémies</strong> (mécanisme des œdèmes incertain) : <span class=\"kw-etio\">malabsorption</span>, <span class=\"kw-etio\">dénutrition</span></li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 257 — Œdèmes des membres inférieurs · 234 — Insuffisance cardiaque · 279 — Cirrhose</em></p>","frequence":0},{"id":"259-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes des traitements symptomatiques d’un syndrome néphrotique","contenu":"<p>Le traitement <span class=\"kw-def\">symptomatique</span> (distinct du traitement étiologique / spécifique, ex. <span class=\"kw-ttt\">corticothérapie</span> du SN à LGM) vise à contrôler les œdèmes, la <span class=\"kw-bio\">protéinurie</span> et à prévenir les complications.</p>\n      <table >\n        <thead><tr><th>Cible</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Œdèmes / rétention sodée</strong></td>\n            <td><span class=\"kw-ttt\">restriction sodée</span> (&lt;<span class=\"kw-chiffre\"> 6 g</span>/j de sel) · <span class=\"kw-ttt\">diurétiques</span> · éviter une déplétion sodée brutale (<span class=\"kw-alerte\">&gt; 1-2 kg/j</span> = risque d'hypovolémie et de thrombose)</td>\n          </tr>\n          <tr>\n            <td><strong>Protéinurie / néphroprotection</strong></td>\n            <td><span class=\"kw-ttt\">IEC ou ARA2</span> (effet antiprotéinurique et antihypertenseur) · contrôle tensionnel</td>\n          </tr>\n          <tr>\n            <td><strong>Risque thrombotique</strong></td>\n            <td>bas de contention · <span class=\"kw-ttt\">anticoagulation préventive</span> si hypoalbuminémie durable <span class=\"kw-chiffre\">&lt; 20 g/L</span></td>\n          </tr>\n          <tr>\n            <td><strong>Hyperlipidémie</strong></td>\n            <td><span class=\"kw-ttt\">statine</span> uniquement si SN <span class=\"kw-clinique\">durable (&gt; 6 mois) résistant</span> au traitement spécifique</td>\n          </tr>\n          <tr>\n            <td><strong>Risque infectieux</strong></td>\n            <td>vaccinations <span class=\"kw-ttt\">anti-pneumococcique</span> et <span class=\"kw-ttt\">anti-grippale</span> — <span class=\"kw-alerte\">pas d'antibioprophylaxie</span> ❌</td>\n          </tr>\n          <tr>\n            <td><strong>Nutrition</strong></td>\n            <td>régime <span class=\"kw-clinique\">normoprotidique</span> (<span class=\"kw-chiffre\">1-1,5 g/kg/j</span>) — <span class=\"kw-ci\">pas de régime hyperprotidique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Deux réflexes thérapeutiques transverses : <span class=\"kw-ttt\">IEC/ARA2</span> antiprotéinuriques + <span class=\"kw-ttt\">restriction sodée &lt; 6 g/j</span>. Et un piège : la déplétion par <span class=\"kw-ttt\">diurétiques</span> doit rester <span class=\"kw-alerte\">progressive</span> (&lt;<span class=\"kw-chiffre\"> 1-2 kg</span>/j) sous peine d'aggraver hypovolémie et thrombose.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — HTA · 226 — MTEV · 330 — Classes de médicaments (<span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-ttt\">IEC</span>)</em></p>","frequence":1},{"id":"259-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’enquête étiologique d’une protéinurie, d’un syndrome néphrotique, les indications de la biopsie rénale chez l’adulte et chez l’enfant","contenu":"<p>Objectif <span class=\"kw-alerte\">à très fort rendement EDN</span> ⭐⭐⭐. L'enquête étiologique précède la décision de <span class=\"kw-def\">biopsie rénale (PBR)</span>, dont les <strong>indications et <span class=\"kw-ci\">contre-indications</span></strong> sont à connaître par cœur.</p>\n      <p><strong>1 · Enquête étiologique — démarche après diagnostic positif d'un SN</strong></p>\n      <ol>\n        <li>établir le caractère <span class=\"kw-clinique\">pur ou impur</span></li>\n        <li>préciser les <span class=\"kw-clinique\">modalités d'installation</span> et l'ancienneté des œdèmes (jours / semaines)</li>\n        <li>rechercher un <span class=\"kw-etio\">facteur déclenchant</span> : médicaments (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">lithium</span>, interféron), vaccination, <span class=\"kw-clinique\">syndrome infectieux récent</span></li>\n        <li>rechercher des <span class=\"kw-etio\">signes extra-rénaux</span> d'une maladie générale : angine, purpura / lésions cutanées, arthralgies, adénopathies</li>\n      </ol>\n      <p><strong>2 · Indications de la biopsie rénale</strong> — la PBR est <span class=\"kw-alerte\">toujours indispensable</span> face à un SN, <strong>SAUF</strong> dans les situations suivantes :</p>\n      <table >\n        <thead><tr><th>Situation où la PBR n'est PAS faite d'emblée</th><th>Conditions</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ci\"><strong>Dangerosité de la biopsie</strong></span></td><td>rein unique, trouble de l'hémostase…</td></tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>SN à LGM</strong></span> (néphrose lipoïdique)</td>\n            <td><span class=\"kw-clinique\">enfant de 1 à 10 ans</span> (jusqu'à<span class=\"kw-chiffre\"> 11 ans</span> selon la dernière édition de pédiatrie) + <span class=\"kw-clinique\">SN pur</span> + <span class=\"kw-clinique\">pas de signes extra-rénaux</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Glomérulopathie diabétique</strong></span></td>\n            <td><strong>PBR non indiquée si :</strong> diabète ancien + <span class=\"kw-clinique\">rétinopathie diabétique</span> + SN <span class=\"kw-clinique\">sans hématurie</span><br><strong>PBR indiquée si :</strong> diabète récent (&lt;<span class=\"kw-chiffre\"> 5-10 ans</span>), <span class=\"kw-alerte\">sans rétinopathie</span>, signes extra-rénaux ; ou syndrome glomérulaire <span class=\"kw-alerte\">rapidement progressif</span> (IR / <span class=\"kw-bio\">protéinurie</span> / <span class=\"kw-bio\">hématurie</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Glomérulopathie héréditaire</strong></span> (ex. Alport)</td>\n            <td>déjà identifiée dans la famille, si aucun traitement spécifique n'est à proposer</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Suspicion d'amylose (adulte)</strong></span></td>\n            <td>si la <span class=\"kw-clinique\">biopsie des glandes salivaires accessoires</span> établit le diagnostic (maladie systémique, dépôts semblables dans le rein)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>3 · Indications de la PBR chez l'enfant</strong></p>\n      <table >\n        <thead><tr><th>Type de <span class=\"kw-bio\">protéinurie</span></th><th>Indication de PBR</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Tubulaire</strong></span></td>\n            <td>si associée à une <span class=\"kw-clinique\">insuffisance rénale organique</span> et/ou des <span class=\"kw-alerte\">signes systémiques / atteintes extra-rénales</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Glomérulaire permanente non orthostatique</strong></span></td>\n            <td>PBR, <strong>SAUF :</strong> GNA typique avec <span class=\"kw-clinique\">baisse transitoire du C3</span> ; ou <span class=\"kw-clinique\">SN pur de l'enfant de 1 à 11 ans</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Drapeau diagnostique.</strong> Devant un SN, deux dispenses de biopsie à retenir absolument : l'<span class=\"kw-alerte\">enfant 1-11 ans avec SN pur</span> (= LGM présumée, <span class=\"kw-ttt\">corticothérapie</span> d'emblée) et le <span class=\"kw-alerte\">diabétique ancien avec rétinopathie et SN sans hématurie</span> (= glomérulopathie diabétique présumée). Hors de ces cadres, la PBR s'impose.</div>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Avis néphrologique systématique si <span class=\"kw-bio\">protéinurie</span> permanente <span class=\"kw-chiffre\">&gt; 0,5 g/j</span>. La <span class=\"kw-clinique\">biopsie des glandes salivaires accessoires</span> peut remplacer la PBR pour diagnostiquer une amylose.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — Diabète et complications · 320 — Myélome / amylose AL · 261 — Néphropathie glomérulaire</em></p>","frequence":3},{"id":"259-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales causes de syndrome néphrotique","contenu":"<p>Les causes de SN se répartissent en formes <span class=\"kw-def\">secondaires</span> (cause générale identifiable) et <span class=\"kw-def\">primitives</span> (idiopathiques, définies par l'histologie).</p>\n      <p><strong>Syndromes néphrotiques secondaires</strong></p>\n      <table >\n        <thead><tr><th>Cadre</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\"><strong>1ʳᵉ cause (adulte)</strong></span></td><td><span class=\"kw-etio\">Diabète</span> = 1ʳᵉ cause de SN chez l'adulte</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Maladies générales</strong></span></td><td>lupus érythémateux disséminé · cryoglobulinémie · <span class=\"kw-etio\">amylose AL</span> primitive / myélome · <span class=\"kw-etio\">amylose AA</span> (maladie inflammatoire chronique)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Cancers · hémopathies</strong></span></td><td>tumeurs solides (<span class=\"kw-etio\">cancer pulmonaire</span>) · hémopathies (myélome, <span class=\"kw-etio\">lymphome non hodgkinien</span>) · gammapathie monoclonale isolée · cryoglobulinémie</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Infections</strong></span></td><td><span class=\"kw-etio\">VHB, VHC, VIH</span> · GNA post-infectieuse (streptocoque, pneumocoque) · infection d'un shunt atrio-ventriculaire · paludisme, syphilis, bilharziose</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Médicaments</strong></span></td><td><span class=\"kw-ttt\">AINS</span> · <span class=\"kw-ttt\">lithium</span> · D-pénicillamine · traitements anti-VEGF</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Grossesse</strong></span></td><td>pré-éclampsie</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Syndromes néphrotiques primitifs</strong> — évoqués si l'enquête étiologique est <span class=\"kw-clinique\">négative</span> (pas de cause évidente, pas de signes extra-rénaux) ; définis selon le type histologique.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Place</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Glomérulopathie extra-membraneuse (GEM)</strong></span></td><td><span class=\"kw-alerte\">2ⁿᵈ cause de SN de l'adulte</span> (après le diabète)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>SN idiopathique</strong></span> (SN à LGM, HSF primitive)</td><td><span class=\"kw-alerte\">1ʳᵉ cause de SN de l'enfant</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir — les 3 repères « causes ».</strong> 1ʳᵉ cause de SN chez l'<span class=\"kw-clinique\">adulte</span> = <span class=\"kw-etio\">diabète</span> ; 2ⁿᵈ cause de l'adulte = <span class=\"kw-etio\">GEM</span> ; 1ʳᵉ cause de SN chez l'<span class=\"kw-clinique\">enfant</span> = <span class=\"kw-etio\">SN à LGM</span> (idiopathique).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — Diabète · 194 — Lupus systémique & SAPL · 320 — Myélome · 167 — Hépatites virales · 169 — VIH</em></p>","frequence":0}],"astuces":[],"strategie":{"hospit":"<p><strong>Protéinurie permanente</strong></p><p>Orientation selon le <span class=\"kw-clinique\">débit</span>, la <span class=\"kw-clinique\">composition</span> (EPU) et les <span class=\"kw-clinique\">anomalies associées</span></p><ul><li><span class=\"kw-def\">Protéinurie permanente</span> &gt; <span class=\"kw-chiffre\">0,5 g/j</span> → <span class=\"kw-alerte\">avis néphrologique</span></li></ul><p><strong>Protéinurie transitoire <span class=\"q\">— effort · fièvre · orthostatique</span></strong></p><p>Ces protéinuries <span class=\"kw-alerte\">n'entraînent jamais</span> œdèmes, HTA, hypoalbuminémie ni insuffisance rénale</p><ul><li><span class=\"kw-clinique\">Effort</span> ou <span class=\"kw-clinique\">fièvre prolongée</span> : contrôle à distance, <span class=\"kw-ttt\">aucun bilan</span> si normalisation en <span class=\"kw-chiffre\">1 à 2 semaines</span></li><li><span class=\"kw-def\">Orthostatique</span> (<span class=\"kw-chiffre\">12-16 ans</span>, adolescent longiligne) : <span class=\"kw-ttt\">aucun examen</span> une fois confirmée, disparaît avant <span class=\"kw-chiffre\">20 ans</span></li></ul><p><strong>Syndrome néphrotique <span class=\"q\">— qui biopsier ?</span></strong></p><p><span class=\"kw-ci\">PBR contre-indiquée</span> si rein unique ou trouble de l'hémostase</p><ul><li><span class=\"kw-ttt\">Biopsie rénale (PBR)</span> indispensable face à un SN, SAUF dispenses</li><li>Dispense : <span class=\"kw-clinique\">enfant 1-11 ans</span> + <span class=\"kw-clinique\">SN pur</span> + pas de signe extra-rénal → <span class=\"kw-etio\">SN à LGM</span> présumé (<span class=\"kw-ttt\">corticothérapie</span> d'emblée)</li><li>Dispense : <span class=\"kw-etio\">diabète</span> ancien + <span class=\"kw-clinique\">rétinopathie diabétique</span> + SN <span class=\"kw-clinique\">sans hématurie</span> → glomérulopathie diabétique présumée</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Thrombose des veines rénales</span> → migration vers la VCI → <span class=\"kw-alerte\">risque d'embolie pulmonaire</span> (surtout <span class=\"kw-etio\">GEM</span> / <span class=\"kw-etio\">amylose</span>)</li><li><span class=\"kw-alerte\">Thromboses artérielles</span> (tous territoires) et <span class=\"kw-clinique\">veineuses</span> (sinus veineux cérébral, veines rénales)</li><li><span class=\"kw-alerte\">Sepsis</span> sur <span class=\"kw-etio\">érysipèle</span> évoluant vers <span class=\"kw-clinique\">cellulite</span> ; <span class=\"kw-etio\">péritonite primitive</span> à pneumocoque (enfant) ; <span class=\"kw-alerte\">varicelle maligne</span></li><li>Infection à <span class=\"kw-etio\">bactéries encapsulées</span> (pneumocoque, Haemophilus, Klebsielle, méningocoque)</li><li><span class=\"kw-alerte\">Insuffisance rénale aiguë</span> : <span class=\"kw-clinique\">IRA fonctionnelle</span> (hypovolémie) ou <span class=\"kw-clinique\">NTA</span></li><li>SN <span class=\"kw-alerte\">impur</span> : <span class=\"kw-clinique\">hématurie microscopique</span> · <span class=\"kw-clinique\">HTA</span> · <span class=\"kw-clinique\">insuffisance rénale organique</span></li><li><span class=\"kw-alerte\">Syndrome glomérulaire rapidement progressif</span> : insuffisance rénale + <span class=\"kw-bio\">protéinurie</span> + <span class=\"kw-bio\">hématurie</span></li></ul>","principes":"<p>Traitement <span class=\"kw-def\">symptomatique</span> (distinct du traitement <span class=\"kw-etio\">étiologique / spécifique</span>) : contrôler les œdèmes et la <span class=\"kw-bio\">protéinurie</span>, prévenir les complications. Deux réflexes transverses : <span class=\"kw-ttt\">IEC / ARA2</span> antiprotéinuriques + <span class=\"kw-ttt\">restriction sodée</span> &lt; <span class=\"kw-chiffre\">6 g/j</span>.</p><p><strong>Œdèmes / rétention sodée</strong></p><p><span class=\"kw-ci\">Déplétion sodée brutale</span> <span class=\"kw-ci\">à éviter</span> (<span class=\"kw-alerte\">&gt; 1-2 kg/j</span> = risque d'hypovolémie et de thrombose)</p><ul><li><span class=\"kw-ttt\">Restriction sodée</span> &lt; <span class=\"kw-chiffre\">6 g/j</span> de sel + <span class=\"kw-ttt\">diurétiques</span></li></ul><p><strong>Protéinurie / néphroprotection</strong></p><ul><li><span class=\"kw-ttt\">IEC ou ARA2</span> : effet antiprotéinurique et antihypertenseur</li><li>Contrôle <span class=\"kw-clinique\">tensionnel</span></li></ul><p><strong>Risque thrombotique</strong></p><ul><li>Bas de contention</li><li><span class=\"kw-ttt\">Anticoagulation préventive</span> si <span class=\"kw-bio\">hypoalbuminémie</span> durable &lt; <span class=\"kw-chiffre\">20 g/L</span></li></ul><p><strong>Risque infectieux</strong></p><p><span class=\"kw-ci\">Pas d'antibioprophylaxie</span></p><ul><li>Vaccinations <span class=\"kw-ttt\">anti-pneumococcique</span> et <span class=\"kw-ttt\">anti-grippale</span></li></ul><p><strong>Hyperlipidémie</strong></p><ul><li><span class=\"kw-ttt\">Statine</span> uniquement si SN <span class=\"kw-clinique\">durable</span> (&gt; <span class=\"kw-chiffre\">6 mois</span>) résistant au traitement spécifique (<span class=\"kw-etio\">HSF</span>, <span class=\"kw-etio\">GEM</span>)</li></ul><p><strong>Nutrition</strong></p><p><span class=\"kw-ci\">Pas de régime hyperprotidique</span></p><ul><li>Régime <span class=\"kw-clinique\">normoprotidique</span> <span class=\"kw-chiffre\">1-1,5 g/kg/j</span></li></ul>","suivi":"<p><strong>Cardio-vasculaire & rénal</strong></p><ul><li><span class=\"kw-clinique\">HTA</span> très fréquente sur glomérulonéphrite chronique → néphroprotection</li><li><span class=\"kw-clinique\">IRC</span> : glomérulopathie + néphrotoxicité tubulaire de la <span class=\"kw-bio\">protéinurie</span> (fibrose interstitielle) + HTA non contrôlée</li><li><span class=\"kw-clinique\">Hyperlipidémie</span> mixte athérogène, <span class=\"kw-clinique\">corrélée à la sévérité</span> du SN</li></ul><p><strong>Nutrition & croissance</strong></p><ul><li><span class=\"kw-clinique\">Dénutrition protidique</span> / atrophie musculaire après <span class=\"kw-ttt\">corticothérapie</span> prolongée</li><li><span class=\"kw-clinique\">Retard de croissance</span> de l'enfant (la <span class=\"kw-ttt\">corticothérapie</span> bloque le pic pubertaire)</li></ul><p><strong>Métabolique & médicaments</strong></p><ul><li>Carences par fuite des protéines porteuses : <span class=\"kw-bio\">vitamine D</span>, <span class=\"kw-bio\">hypothyroïdie</span> ; baisse fer / cuivre / zinc</li><li><span class=\"kw-alerte\">Risque de surdosage</span> des médicaments liés à l'<span class=\"kw-bio\">albumine</span> : <span class=\"kw-ttt\">AVK</span>, <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">statines</span></li></ul>"},"liensGlobaux":[{"href":"https://manuel4.cuen.fr/spip.php?rubrique11","label":"Collège CUEN — Protéinurie & Syndrome néphrotique"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/nephrologie-chirurgie-urologique/proteinurie-syndrome-nephrotique-hematurie","label":"Collège de Pédiatrie — Protéinurie, SN, hématurie (enfant)"}],"cards":[]};